// openResolveFixture is the resolve-test fixture: the identity service and
// its store handle BOTH retained (the LIVE intersection must hit a real
// libraries table, so the seeds go through the store's own CreateLibrary),
// plus one seeded user whose row id comes back.
func openResolveFixture(t *testing.T, username string) (*Service, *store.Store, int64) {
	t.Helper()
	stamp := time.Date(2026, 11, 4, 12, 0, 0, 0, time.UTC)
	st := openIdentityStore(t)
	s := NewService(st, func() time.Time { return stamp })
	u, err := s.Create(context.Background(), username, "pw")
	if err != nil {
		t.Fatalf("Create %q: %v", username, err)
	}
	return s, st, u.ID
}

// mustCreateLibrary seeds one library via the store's own API; a seed
// failure is always fatal.
func mustCreateLibrary(t *testing.T, st *store.Store, root string) int64 {
	t.Helper()
	id, err := st.CreateLibrary(context.Background(), "testmod", root, root)
	if err != nil {
		t.Fatalf("CreateLibrary %q: %v", root, err)
	}
	return id
}

// TestResolveViewerGrants covers the grant-resolution joint (task 3.4): the
// union across the user's groups, orphaned grant rows invisible with no
// error, the zero-group user collapsing to the empty-set (UserID-carrying)
// User viewer, and the admin role overriding everything.
func TestResolveViewerGrants(t *testing.T) {
	ctx := context.Background()

	t.Run("union_across_groups", func(t *testing.T) {
		s, st, uid := openResolveFixture(t, "alia")
		l1 := mustCreateLibrary(t, st, "/lib/one")
		l2 := mustCreateLibrary(t, st, "/lib/two")
		l3 := mustCreateLibrary(t, st, "/lib/three")
		if _, err := s.CreateGroup(ctx, "Movies"); err != nil {
			t.Fatalf("CreateGroup Movies: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "TV"); err != nil {
			t.Fatalf("CreateGroup TV: %v", err)
		}
		if err := s.AddCollection(ctx, "Movies", l1, 0); err != nil {
			t.Fatalf("AddCollection Movies/l1: %v", err)
		}
		if err := s.AddCollection(ctx, "Movies", l2, 1); err != nil {
			t.Fatalf("AddCollection Movies/l2: %v", err)
		}
		if err := s.AddCollection(ctx, "TV", l2, 0); err != nil {
			t.Fatalf("AddCollection TV/l2: %v", err)
		}
		if err := s.AddCollection(ctx, "TV", l3, 1); err != nil {
			t.Fatalf("AddCollection TV/l3: %v", err)
		}
		if err := s.AddUser(ctx, "Movies", "alia"); err != nil {
			t.Fatalf("AddUser Movies: %v", err)
		}
		if err := s.AddUser(ctx, "TV", "alia"); err != nil {
			t.Fatalf("AddUser TV: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer: %v", err)
		}
		if v.Admin {
			t.Fatalf("Admin = true, want a scoped User viewer")
		}
		if v.UserID != uid {
			t.Fatalf("UserID = %d, want %d", v.UserID, uid)
		}
		// l2 rides BOTH groups — the union carries it exactly once.
		if !slices.Equal(v.VisibleLibraryIDs, []int64{l1, l2, l3}) {
			t.Fatalf("VisibleLibraryIDs = %v, want the sorted union [%d %d %d]",
				v.VisibleLibraryIDs, l1, l2, l3)
		}
		if len(v.ChainMutes) != 0 {
			t.Fatalf("ChainMutes = %v, want empty (no group carries mutes)", v.ChainMutes)
		}
	})

	t.Run("orphan_invisible", func(t *testing.T) {
		s, st, uid := openResolveFixture(t, "alia")
		l1 := mustCreateLibrary(t, st, "/lib/live")
		if _, err := s.CreateGroup(ctx, "Main"); err != nil {
			t.Fatalf("CreateGroup Main: %v", err)
		}
		// The ORPHAN: a grant row whose library was never created (the
		// DeleteLibrary aftermath, without the cascade — the exact shape
		// D5 declares harmless).
		if err := s.AddCollection(ctx, "Main", 99999, 0); err != nil {
			t.Fatalf("AddCollection orphan: %v", err)
		}
		if err := s.AddCollection(ctx, "Main", l1, 1); err != nil {
			t.Fatalf("AddCollection live: %v", err)
		}
		if err := s.AddUser(ctx, "Main", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer (orphan present): %v", err)
		}
		if !slices.Equal(v.VisibleLibraryIDs, []int64{l1}) {
			t.Fatalf("VisibleLibraryIDs = %v, want only the live library [%d]", v.VisibleLibraryIDs, l1)
		}
	})

	t.Run("zero_groups_fail_closed", func(t *testing.T) {
		s, _, uid := openResolveFixture(t, "bea")
		// bea is in NO group. An empty set is NOT the zero Viewer: UserID
		// must be carried (ledger slot stamping reads it) and the set must
		// be empty — visibleWhere turns it into 1=0 (fail closed).
		v, err := s.ResolveViewer(ctx, uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer (no groups): %v", err)
		}
		if v.UserID != uid || len(v.VisibleLibraryIDs) != 0 || v.Admin || len(v.ChainMutes) != 0 {
			t.Fatalf("viewer = %+v, want UserID %d, empty set, non-admin, no mutes", v, uid)
		}
	})

	t.Run("admin_overrides", func(t *testing.T) {
		s, st, uid := openResolveFixture(t, "alia")
		l1 := mustCreateLibrary(t, st, "/lib/one")
		if _, err := s.CreateGroup(ctx, "Main"); err != nil {
			t.Fatalf("CreateGroup Main: %v", err)
		}
		if err := s.AddCollection(ctx, "Main", l1, 0); err != nil {
			t.Fatalf("AddCollection: %v", err)
		}
		if err := s.AddUser(ctx, "Main", "alia"); err != nil {
			t.Fatalf("AddUser: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, true)
		if err != nil {
			t.Fatalf("ResolveViewer(admin): %v", err)
		}
		if !v.Admin || v.UserID != 0 || len(v.VisibleLibraryIDs) != 0 || len(v.ChainMutes) != 0 {
			t.Fatalf("ResolveViewer(admin) = %+v, want the all-seeing Admin viewer", v)
		}
	})
}

// TestResolveViewerMuteWins covers the mute-merge joint (task 3.4, D8):
// MUTE-WINS across overlapping groups, a mute surviving groups without one,
// the admin override, and the malformed-doc decision (skip that group's
// mutes silently; grants still resolve).
func TestResolveViewerMuteWins(t *testing.T) {
	ctx := context.Background()

	t.Run("overlap_merges_both", func(t *testing.T) {
		s, st, uid := openResolveFixture(t, "alia")
		l1 := mustCreateLibrary(t, st, "/lib/one")
		if _, err := s.CreateGroup(ctx, "A"); err != nil {
			t.Fatalf("CreateGroup A: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "B"); err != nil {
			t.Fatalf("CreateGroup B: %v", err)
		}
		if err := s.SetGroupDoc(ctx, "A", `{"mutes":{"srcX":true}}`, 1); err != nil {
			t.Fatalf("SetGroupDoc A: %v", err)
		}
		if err := s.SetGroupDoc(ctx, "B", `{"mutes":{"srcY":true}}`, 1); err != nil {
			t.Fatalf("SetGroupDoc B: %v", err)
		}
		if err := s.AddCollection(ctx, "A", l1, 0); err != nil {
			t.Fatalf("AddCollection A: %v", err)
		}
		if err := s.AddCollection(ctx, "B", l1, 0); err != nil {
			t.Fatalf("AddCollection B: %v", err)
		}
		if err := s.AddUser(ctx, "A", "alia"); err != nil {
			t.Fatalf("AddUser A: %v", err)
		}
		if err := s.AddUser(ctx, "B", "alia"); err != nil {
			t.Fatalf("AddUser B: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer: %v", err)
		}
		if !v.ChainMutes["srcX"] || !v.ChainMutes["srcY"] {
			t.Fatalf("ChainMutes = %v, want BOTH srcX and srcY muted (mute-wins union)", v.ChainMutes)
		}
		if !slices.Equal(v.VisibleLibraryIDs, []int64{l1}) {
			t.Fatalf("VisibleLibraryIDs = %v, want [%d] (mutes never touch visibility)", v.VisibleLibraryIDs, l1)
		}
	})

	t.Run("mute_survives_clean_group", func(t *testing.T) {
		s, _, uid := openResolveFixture(t, "alia")
		if _, err := s.CreateGroup(ctx, "A"); err != nil {
			t.Fatalf("CreateGroup A: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "B"); err != nil {
			t.Fatalf("CreateGroup B: %v", err)
		}
		if err := s.SetGroupDoc(ctx, "A", `{"mutes":{"srcX":true}}`, 1); err != nil {
			t.Fatalf("SetGroupDoc A: %v", err)
		}
		// B carries NO mutes — it must not lift A's mute.
		if err := s.SetGroupDoc(ctx, "B", `{}`, 1); err != nil {
			t.Fatalf("SetGroupDoc B: %v", err)
		}
		if err := s.AddUser(ctx, "A", "alia"); err != nil {
			t.Fatalf("AddUser A: %v", err)
		}
		if err := s.AddUser(ctx, "B", "alia"); err != nil {
			t.Fatalf("AddUser B: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer: %v", err)
		}
		if !v.ChainMutes["srcX"] {
			t.Fatalf("ChainMutes = %v, want srcX still muted (union of mutes)", v.ChainMutes)
		}
		if len(v.ChainMutes) != 1 {
			t.Fatalf("ChainMutes = %v, want exactly one muted plugin", v.ChainMutes)
		}
	})

	t.Run("admin_has_no_mutes", func(t *testing.T) {
		s, _, uid := openResolveFixture(t, "alia")
		if _, err := s.CreateGroup(ctx, "A"); err != nil {
			t.Fatalf("CreateGroup A: %v", err)
		}
		if err := s.SetGroupDoc(ctx, "A", `{"mutes":{"srcX":true}}`, 1); err != nil {
			t.Fatalf("SetGroupDoc A: %v", err)
		}
		if err := s.AddUser(ctx, "A", "alia"); err != nil {
			t.Fatalf("AddUser A: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, true)
		if err != nil {
			t.Fatalf("ResolveViewer(admin): %v", err)
		}
		if !v.Admin || len(v.ChainMutes) != 0 {
			t.Fatalf("ResolveViewer(admin) = %+v, want the Admin viewer with NO mutes", v)
		}
	})

	t.Run("malformed_doc_skipped_grants_resolve", func(t *testing.T) {
		s, st, uid := openResolveFixture(t, "alia")
		l1 := mustCreateLibrary(t, st, "/lib/one")
		if _, err := s.CreateGroup(ctx, "A"); err != nil {
			t.Fatalf("CreateGroup A: %v", err)
		}
		if _, err := s.CreateGroup(ctx, "B"); err != nil {
			t.Fatalf("CreateGroup B: %v", err)
		}
		if err := s.SetGroupDoc(ctx, "A", `{"mutes":{"srcX":true}}`, 1); err != nil {
			t.Fatalf("SetGroupDoc A: %v", err)
		}
		// B's doc is garbage — the documented decision: skip B's mutes
		// silently, never error, A's mutes and the grants still resolve.
		if err := s.SetGroupDoc(ctx, "B", `not json at all`, 1); err != nil {
			t.Fatalf("SetGroupDoc B (malformed stored verbatim): %v", err)
		}
		if err := s.AddCollection(ctx, "A", l1, 0); err != nil {
			t.Fatalf("AddCollection A: %v", err)
		}
		if err := s.AddCollection(ctx, "B", l1, 0); err != nil {
			t.Fatalf("AddCollection B: %v", err)
		}
		if err := s.AddUser(ctx, "A", "alia"); err != nil {
			t.Fatalf("AddUser A: %v", err)
		}
		if err := s.AddUser(ctx, "B", "alia"); err != nil {
			t.Fatalf("AddUser B: %v", err)
		}

		v, err := s.ResolveViewer(ctx, uid, false)
		if err != nil {
			t.Fatalf("ResolveViewer (malformed doc present) = %v, want nil error", err)
		}
		if !v.ChainMutes["srcX"] {
			t.Fatalf("ChainMutes = %v, want srcX (group A's parse) still applied", v.ChainMutes)
		}
		if len(v.ChainMutes) != 1 {
			t.Fatalf("ChainMutes = %v, want only group A's mute", v.ChainMutes)
		}
		if !slices.Equal(v.VisibleLibraryIDs, []int64{l1}) {
			t.Fatalf("VisibleLibraryIDs = %v, want [%d] (grants unaffected by doc hygiene)", v.VisibleLibraryIDs, l1)
		}
	})
}
